-- Idempotent Domternal-compatible demo articles. Re-running updates only these five slugs.
INSERT INTO blog_posts (title, slug, excerpt, content, status, visibility, created_at, updated_at, published_at) VALUES
('An Introduction to Python', 'introduction-to-python', 'Learn Python’s readable syntax, core data structures, and a practical first program—then see how to keep learning.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python is a general-purpose programming language designed to make code approachable and expressive. It is used for automation, web services, data analysis, scientific computing, and much more. Its friendly syntax makes it a strong first language, while its ecosystem supports production systems at every scale."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Your first Python program"}]},{"type":"paragraph","content":[{"type":"text","text":"Install Python 3 from the "},{"type":"text","text":"official downloads page","marks":[{"type":"link","attrs":{"href":"https://www.python.org/downloads/"}}]},{"type":"text","text":" and create a file named hello.py. Then write:"}]},{"type":"codeBlock","attrs":{"language":"python"},"content":[{"type":"text","text":"name = input(\"What is your name? \" )\nprint(f\"Hello, {name}!\")"}]},{"type":"paragraph","content":[{"type":"text","text":"Run it from a terminal with "},{"type":"text","text":"python hello.py","marks":[{"type":"code"}]},{"type":"text","text":". The program asks a question, stores the response in a variable, and prints a personalized greeting."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A few building blocks"}]},{"type":"paragraph","content":[{"type":"text","text":"Names point to values. Strings hold text, numbers represent quantities, and lists keep an ordered collection. Python infers the value type, so you can start with a simple assignment:"}]},{"type":"codeBlock","attrs":{"language":"python"},"content":[{"type":"text","text":"topics = [\"variables\", \"loops\", \"functions\"]\nfor topic in topics:\n    print(topic)"}]},{"type":"paragraph","content":[{"type":"text","text":"The loop visits each item in turn. Indentation is meaningful in Python: it marks the body of a loop or function, so keep it consistent (four spaces is the usual convention)."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Learn by making small things"}]},{"type":"paragraph","content":[{"type":"text","text":"A practical path is to learn one idea, use it in a tiny project, and improve the project as your knowledge grows. Try a command-line quiz, a file organizer, or a script that summarizes a text file. Small feedback loops make mistakes easier to understand and progress easier to see."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Practice strings, numbers, conditions, and loops."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Break repeated logic into small functions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Read tracebacks from the bottom to find where an error occurred."}]}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"The best first program is one you understand well enough to change."}]}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","text":"Python rewards curiosity. Once the fundamentals feel comfortable, choose a problem you care about and let it guide which libraries and concepts you learn next."}]}]}', 'published', 'public', now(), now(), now()),
('Formatting That Carries Meaning', 'formatting-that-carries-meaning', 'A tour of headings, inline formatting, links, and quotations supported by the shared Domternal document.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Good writing starts with a clear structure. Use "},{"type":"text","text":"bold emphasis","marks":[{"type":"bold"}]},{"type":"text","text":" for the central idea, "},{"type":"text","text":"italics","marks":[{"type":"italic"}]},{"type":"text","text":" for a gentle aside, and inline code when naming a value or command."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Make the hierarchy visible"}]},{"type":"paragraph","content":[{"type":"text","text":"Headings give readers landmarks. A "},{"type":"text","text":"useful reference","marks":[{"type":"link","attrs":{"href":"https://developer.mozilla.org/en-US/docs/Web/HTML/Element/Heading_Elements"}}]},{"type":"text","text":" can add context without interrupting the paragraph."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"A quotation block makes a voice or key takeaway distinct from the surrounding explanation."}]}]},{"type":"paragraph","content":[{"type":"text","text":"These marks and blocks live in the same JSON document in both editor modes; changing the presentation does not change the saved format."}]}]}', 'published', 'public', now(), now(), now()),
('Building a Page One Block at a Time', 'building-a-page-one-block-at-a-time', 'Lists, code blocks, and dividers show how ordinary document blocks can organize a practical walkthrough.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A useful tutorial can be assembled from small, movable blocks. Start with a short checklist:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain the goal before showing the steps."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep each action focused on one outcome."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add a code sample only when it clarifies the idea."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A small JavaScript example"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Read a value."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Transform it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return a result that is easy to verify."}]}]}]},{"type":"codeBlock","attrs":{"language":"javascript"},"content":[{"type":"text","text":"function formatTitle(title) {\n  return title.trim().replace(/\\s+/g, \" \" );\n}"}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","text":"The Notion-style controls can help insert, reorder, and manage these blocks; the persisted document remains standard content JSON rather than an editor-specific mode setting."}]}]}', 'published', 'public', now(), now(), now()),
('Images Belong in the Story', 'images-belong-in-the-story', 'An image, descriptive alternative text, and a caption can complement the words without replacing them.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A relevant image can make a technical article easier to scan. Add it where it supports the nearby explanation, and write alternative text that conveys its purpose."}]},{"type":"image","attrs":{"src":"https://images.unsplash.com/photo-1498050108023-c5249f4df085?auto=format&fit=crop&w=1200&q=80","alt":"Laptop on a desk showing a code editor","title":"A workspace for building on the web"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Keep images accessible and useful"}]},{"type":"paragraph","content":[{"type":"text","text":"In the admin editor, images can be uploaded or inserted as supported HTTP(S) URLs. The image node is saved with the document, and "},{"type":"text","text":"accessible descriptions","marks":[{"type":"bold"}]},{"type":"text","text":" help readers using assistive technology."}]},{"type":"paragraph","content":[{"type":"text","text":"Image blocks and text use the same JSON document in the Notion-style editor."}]}]}', 'published', 'public', now(), now(), now()),
('Build a Telegram Translator Bot with Python', 'build-a-telegram-translator-bot-with-python', 'A step-by-step project covering BotFather, a Python bot, translation APIs, deployment, and useful media blocks.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In this walkthrough, we will create a small Telegram bot that translates a message when someone replies with /translate. Keep the bot token private and configure it through an environment variable."}]},{"type":"image","attrs":{"src":"https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1200&q=80","alt":"Laptop and phone on a desk","title":"Plan the bot before writing code","align":"center"}},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"1. Create a Telegram bot"}]},{"type":"paragraph","content":[{"type":"text","text":"Open Telegram and message BotFather. Run /newbot, choose a display name, then choose a username ending in bot. Anyone with the token can control your bot, so never publish it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Prepare a Python project"}]},{"type":"paragraph","content":[{"type":"text","text":"Create a folder, a virtual environment, and install the Telegram bot library. Keep secrets out of source control."}]},{"type":"codeBlock","attrs":{"language":"bash"},"content":[{"type":"text","text":"python -m venv .venv\nsource .venv/bin/activate\npip install python-telegram-bot httpx\nexport TELEGRAM_BOT_TOKEN=''paste-your-token-in-your-shell''"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Add a requirements file"}]},{"type":"paragraph","content":[{"type":"text","text":"Record your dependencies in requirements.txt so the same environment can be recreated later."}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"2. Receive a message and translate it"}]},{"type":"paragraph","content":[{"type":"text","text":"Add a handler that receives a reply, extracts the replied-to text, calls a translation provider, and sends the translated result. This simplified example leaves the provider behind a function so you can choose a service and check its terms."}]},{"type":"codeBlock","attrs":{"language":"python"},"content":[{"type":"text","text":"import os\nfrom telegram import Update\nfrom telegram.ext import Application, CommandHandler, ContextTypes\n\nasync def translate_text(text: str, target: str = \"en\") -> str:\n    # Call your chosen translation API here.\n    return f\"[{target}] {text}\"\n\nasync def translate_reply(update: Update, context: ContextTypes.DEFAULT_TYPE):\n    message = update.effective_message\n    if not message:\n        return\n    if not message.reply_to_message:\n        await message.reply_text(\"Reply to a message with /translate\")\n        return\n    source = message.reply_to_message.text or message.reply_to_message.caption\n    if not source:\n        await message.reply_text(\"That message has no translatable text.\")\n        return\n    result = await translate_text(source, target=\"en\")\n    await message.reply_text(result)\n\napp = Application.builder().token(os.environ[\"TELEGRAM_BOT_TOKEN\"]).build()\napp.add_handler(CommandHandler(\"translate\", translate_reply))\napp.run_polling()"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"A bot token is a credential. Never paste a real token into a public post, screenshot, or committed code sample."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Connect a real translation provider"}]},{"type":"paragraph","content":[{"type":"text","text":"Replace the placeholder with an async HTTP request to your chosen translation API. Add request timeouts and handle API errors without exposing credentials to chat users."}]},{"type":"image","attrs":{"src":"https://images.unsplash.com/photo-1498050108023-c5249f4df085?auto=format&fit=crop&w=1200&q=80","alt":"A developer workspace with a laptop","title":"Build and test one step at a time"}},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"3. Test locally, then deploy"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Try the important cases"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Run /translate without replying and confirm the bot explains how to use it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reply to a text message and verify the translated response."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Try a photo caption, an empty message, and a provider timeout."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Choose polling or webhooks"}]},{"type":"paragraph","content":[{"type":"text","text":"Polling is convenient while developing. For a hosted bot, configure a webhook behind HTTPS, keep the process supervised, and rotate the token if it is exposed."}]},{"type":"videoEmbed","attrs":{"src":"https://www.youtube-nocookie.com/embed/M7lc1UVf-VE","title":"Demo video embed"}},{"type":"fileEmbed","attrs":{"src":"https://www.w3.org/WAI/ER/tests/xhtml/testfiles/resources/pdf/dummy.pdf","name":"translation-bot-quick-reference.pdf","mimeType":"application/pdf","display":"card"}},{"type":"fileEmbed","attrs":{"src":"https://raw.githubusercontent.com/github/gitignore/main/Python.gitignore","name":"Python.gitignore","mimeType":"text/plain","display":"card"}},{"type":"fileEmbed","attrs":{"src":"https://www.w3.org/WAI/ER/tests/xhtml/testfiles/resources/pdf/dummy.pdf","name":"bot-project-resource.pdf","mimeType":"application/pdf","display":"link"}},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"4. Keep improving the bot"}]},{"type":"paragraph","content":[{"type":"text","text":"Add language selection, caching, and clear failure messages as follow-up exercises. This sample keeps the provider call explicit so readers can extend it safely."}]}]}', 'published', 'public', now(), now(), now())
ON CONFLICT (slug) DO UPDATE SET title=EXCLUDED.title, excerpt=EXCLUDED.excerpt, content=EXCLUDED.content, status=EXCLUDED.status, visibility=EXCLUDED.visibility, updated_at=now(), published_at=COALESCE(blog_posts.published_at, EXCLUDED.published_at);

UPDATE blog_posts
SET content = jsonb_set(content, '{content}', content->'content' || $json$
[
  {"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. Add language selection"}]},
  {"type":"paragraph","content":[{"type":"text","text":"A useful next improvement is letting each chat choose a target language. Store the selection by chat ID, validate the requested language against your translation provider, and explain the current target in a /language command."}]},
  {"type":"codeBlock","attrs":{"language":"python"},"content":[{"type":"text","text":"from telegram.ext import CommandHandler\n\nasync def set_language(update, context):\n    if not context.args:\n        await update.effective_message.reply_text(\"Usage: /language en\")\n        return\n    target = context.args[0].lower()\n    if target not in {\"en\", \"es\", \"fr\", \"de\"}:\n        await update.effective_message.reply_text(\"Choose en, es, fr, or de.\")\n        return\n    context.chat_data[\"target_language\"] = target\n    await update.effective_message.reply_text(f\"Target language set to {target}.\")\n\napp.add_handler(CommandHandler(\"language\", set_language))"}]},
  {"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"6. Add resilience and good error messages"}]},
  {"type":"paragraph","content":[{"type":"text","text":"Translation providers can rate-limit requests or become temporarily unavailable. Use timeouts, retry only transient errors with a small backoff, and avoid sending internal exception details or provider credentials to Telegram users."}]},
  {"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"7. Protect user privacy"}]},
  {"type":"paragraph","content":[{"type":"text","text":"Messages sent to a translation API leave Telegram and reach another service. Tell users what is processed, avoid storing message text unless you need it, and follow the privacy and retention rules of both Telegram and your chosen provider."}]},
  {"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"8. Deploy with webhooks"}]},
  {"type":"paragraph","content":[{"type":"text","text":"For a public bot, run behind HTTPS and configure Telegram's webhook endpoint. Verify Telegram's secret token header, keep the bot process monitored, and rotate credentials immediately if they leak."}]},
  {"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set TELEGRAM_BOT_TOKEN in the host's secret manager."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configure the webhook URL and a random webhook secret."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check logs and health status without logging message contents or secrets."}]}]}]},
  {"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Troubleshooting checklist"}]},
  {"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the bot does not respond, verify its token, process status, and webhook or polling configuration."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If translation fails, check provider quotas, API status, request timeouts, and supported language codes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If updates are duplicated, make handling idempotent and inspect webhook delivery status."}]}]}]},
  {"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Further exercises"}]},
  {"type":"paragraph","content":[{"type":"text","text":"Add automatic language detection, per-user preferences, caching for repeated phrases, and a /help command. Then write focused tests around empty messages, API timeouts, and language validation before inviting others to use the bot."}]}
]
$json$::jsonb, false)
WHERE slug = 'build-a-telegram-translator-bot-with-python';
